function replaceText(source,oldValue,newValue,marker,label){
  if(marker&&source.includes(marker))return source;
  const first=source.indexOf(oldValue);
  if(first<0)throw new Error(`Patch guard failed: ${label} source signature was not found.`);
  if(source.indexOf(oldValue,first+oldValue.length)>=0)throw new Error(`Patch guard failed: ${label} source signature is not unique.`);
  changed=true;
  return source.replace(oldValue,newValue);
}
function replaceLine(source,pattern,replacement,marker,label){
  if(marker&&source.includes(marker))return source;
  const matches=source.match(new RegExp(pattern.source,pattern.flags.includes('g')?pattern.flags:pattern.flags+'g'))||[];
  if(matches.length!==1)throw new Error(`Patch guard failed: ${label} expected one source line, found ${matches.length}.`);
  changed=true;
  return source.replace(pattern,replacement);
}
function insertBefore(source,anchor,block,marker,label){
  if(source.includes(marker))return source;
  const first=source.indexOf(anchor);
  if(first<0)throw new Error(`Patch guard failed: ${label} anchor was not found.`);
  if(source.indexOf(anchor,first+anchor.length)>=0)throw new Error(`Patch guard failed: ${label} anchor is not unique.`);
  changed=true;
  return source.slice(0,first)+block+'\n\n'+source.slice(first);
}
function insertAfterLine(source,pattern,line,marker,label){
  if(source.includes(marker))return source;
  const match=source.match(pattern);
  if(!match)throw new Error(`Patch guard failed: ${label} line was not found.`);
  changed=true;
  return source.replace(pattern,match[0]+'\n'+line);
}

