    async evaluateCivilDay(reason='active',epochMilliseconds=Date.now()){const parts=await this.activeCivilParts(epochMilliseconds),state=await this.runtime(),previous=state.lastCivilDate||'';if(!previous){await this.updateRuntime({lastCivilDate:parts.date,lastCivilTimeZoneId:parts.timeZoneId});return{status:'initialized',date:parts.date}}if(previous===parts.date){if(state.lastCivilTimeZoneId!==parts.timeZoneId)await this.updateRuntime({lastCivilTimeZoneId:parts.timeZoneId});return{status:'same-date',date:parts.date}}const eventId='day-changed:'+parts.timeZoneId+':'+previous+'>'+parts.date;const results=await this.emitDomainEvent('day-changed',{eventId,entityId:parts.date,current:{date:parts.date,previousDate:previous,timeZoneId:parts.timeZoneId},data:{reason,previousDate:previous,date:parts.date,timeZoneId:parts.timeZoneId}});await this.updateRuntime({lastCivilDate:parts.date,lastCivilTimeZoneId:parts.timeZoneId});return{status:'changed',date:parts.date,results}}
    revisionFingerprint(data,settings,dates,stores){const dateSet=new Set(dates),rows=[];if(stores.includes('settings'))rows.push(['settings',settings.revision||0]);for(const profile of CoreUtil.array(data.dayProfiles))if(dateSet.has(profile.date))rows.push(['dayProfile',profile.id,profile.revision||0]);for(const event of CoreUtil.array(data.events))if([...dateSet].some(date=>event.startDate<=date&&event.endDate>=date))rows.push(['event',event.id,event.revision||0]);for(const block of CoreUtil.array(data.timeBlocks))if(dateSet.has(block.date))rows.push(['block',block.id,block.revision||0]);for(const project of CoreUtil.array(data.projects))rows.push(['project',project.id,project.revision||0]);return CoreUtil.hash(rows.sort((a,b)=>String(a[0]+a[1]).localeCompare(String(b[0]+b[1]))))}
    async evaluateCapacityChanges(stores,dates,lineage=null){if(!stores.some(store=>['events','timeBlocks','dayProfiles','settings'].includes(store)))return[];const [data,settings]=await Promise.all([this.repo.dataset({fresh:true}),this.repo.settings()]),active=await this.activeCivilDate(),targets=new Set(dates?.size?[...dates]:[active]),state=await this.runtime(),signatures={...(state.capacitySignatures||{})},results=[];for(const date of targets){let capacity;try{capacity=CapacityEngine.summary(date,data,settings)}catch{continue}const signature=CoreUtil.hash({physicalLeft:capacity.physicalLeft,focusRemaining:capacity.focusRemaining,projectAvailable:capacity.projectAvailable,status:capacity.status,type:capacity.type?.code,breakdown:capacity.breakdown});if(signatures[date]===signature)continue;const revisionKey=this.revisionFingerprint(data,settings,[date],stores),eventId='capacity-recalculated:'+date+':'+signature+':'+revisionKey,options={eventId,entityId:date,current:{date,physicalLeft:capacity.physicalLeft,focusRemaining:capacity.focusRemaining,projectAvailable:capacity.projectAvailable,status:capacity.status,dayProfile:capacity.type?.code},data:{date,physicalLeft:capacity.physicalLeft,remainingFocus:capacity.focusRemaining,projectAvailable:capacity.projectAvailable,status:capacity.status,dayProfile:capacity.type?.code},...(lineage||{})};results.push(await this.emitDomainEvent('capacity-recalculated',options));signatures[date]=signature}await this.updateRuntime({capacitySignatures:Object.fromEntries(Object.entries(signatures).slice(-62))});return results}
    async evaluateProjectShortfalls(stores,dates,lineage=null){if(!stores.some(store=>['planning-refresh','projects','tasks','timeBlocks','dayProfiles','events','settings'].includes(store)))return[];const [data,settings]=await Promise.all([this.repo.dataset({fresh:true}),this.repo.settings()]),active=await this.activeCivilDate(),week=CoreUtil.startOfWeek(active),context=ProjectAllocator.context(data,settings),state=await this.runtime(),signatures={...(state.projectShortfallSignatures||{})},results=[];for(const project of data.projects.filter(row=>row.status==='Active')){const value=ProjectAllocator.shortfall(project,data.tasks,week,data,settings,context),bucket=value.shortfall>0?Math.max(1,Math.ceil(value.shortfall/60)):0,key=project.id+':'+week,signature=CoreUtil.hash({bucket,demand:value.demand,usable:value.usable,revision:project.revision||0});if(!bucket){signatures[key]=signature;continue}if(signatures[key]===signature)continue;const eventId='project-weekly-shortfall:'+project.id+':'+week+':'+bucket+':'+signature,current={...project,date:active,weekStart:week,shortfall:value.shortfall};results.push(await this.emitDomainEvent('project-weekly-shortfall',{eventId,entityType:'project',entityId:project.id,current,data:{projectId:project.id,weekStart:week,shortfall:value.shortfall,demand:value.demand,usable:value.usable,bucket,causes:value.causes},...(lineage||{})}));signatures[key]=signature}await this.updateRuntime({projectShortfallSignatures:Object.fromEntries(Object.entries(signatures).filter(([key])=>key.endsWith(':'+week)).slice(-100))});return results}
