const onStoresChanged="    async onStoresChanged(stores){await this.waitForExternalOperation();if(stores.includes('rules'))await this.reindex();const affectedDates=new Set(),lineageHints=[];for(const store of stores.filter(name=>this.tracked.includes(name))){const previous=this.snapshots.get(store)||new Map(),current=this.toMap(await this.repo.all(store,{fresh:true}));this.snapshots.set(store,current);const events=store==='settings'?[]:this.diffStore(store,previous,current);for(const event of events){for(const date of this.eventDates(event))affectedDates.add(date);const hint=this.lineageHint(event);if(hint)lineageHints.push(hint);await this.process(event)}if(store==='settings'){const settings=[...current.values()][0],lineage=settings?.ruleLineage;if(lineage?.ruleExecutionId)lineageHints.push({sourceOperationId:lineage.sourceOperationId||'',sourceRuleExecutionId:lineage.ruleExecutionId||'',sourceRuleId:lineage.ruleId||'',parentRuleExecutionId:lineage.parentRuleExecutionId||'',chainDepth:CoreUtil.num(lineage.chainDepth),lineage:CoreUtil.array(lineage.ruleIds)})}}if(!affectedDates.size)affectedDates.add(await this.activeCivilDate());const lineage=lineageHints[0]||null;if(stores.some(store=>['tasks','events','timeBlocks','dayProfiles'].includes(store)))await this.evaluateOverdue();await this.evaluateCapacityChanges(stores,affectedDates,lineage);await this.evaluateProjectShortfalls(stores,affectedDates,lineage);await this.emitPlanningRefresh(stores,affectedDates,lineage)}";
