const processMethod="    async process(event,{mode='production',dataOverride=null,settingsOverride=null}={}){if(!RULE_TRIGGERS[event.type])return[];if(event.chainDepth>MAX_RULE_CHAIN_DEPTH){await this.audit(null,event,'Loop prevented',[],['Maximum rule chain depth reached.']);return[]}const run=async()=>{if(mode==='production'&&await this.alreadyProcessed(event.eventId))return[];const rules=(this.index.get(event.type)||[]).filter(rule=>!event.sourceRuleId||rule.id!==event.sourceRuleId).filter(rule=>!CoreUtil.array(event.lineage).includes(rule.id));if(!rules.length){if(mode==='production')await this.rememberEvent(event.eventId);return[]}const data=dataOverride||await this.repo.dataset({fresh:true}),settings=settingsOverride||await this.repo.settings(),context=this.context(event,data,settings),plans=[];for(const rule of rules){const plan=this.evaluate(rule,event,context);if(plan.matched)plans.push(plan)}const resolved=this.resolveConflicts(plans),results=[];for(const plan of resolved)results.push(await this.applyPlan(plan,event,context,{mode}));if(mode==='production')await this.rememberEvent(event.eventId);return results};if(mode!=='production')return run();let result;try{result=await this.operationLocks.withExclusiveLock('Rule automation',run)}catch(error){if(error.code==='CROSS-TAB-LOCK-001')return[];throw error}if(!this.flushingDeferred)await this.flushDeferredEvents();return result}";
