const dayPlan="    async applyDayPlan(plan){const snapshot=await this.snapshots.create(`Before ${plan.rescue?'Rescue Day':plan.minimum?'Minimum Day':'Generate My Day'}`,'pre-schedule'),journal=await this.journal.begin(plan.rescue?'Rescue Day':plan.minimum?'Minimum Day':'Generate Day',['timeBlocks','tasks','activityLog'],snapshot.id);try{await this.repo.transaction(['timeBlocks','tasks','activityLog'],async tx=>{for(const block of plan.remove)await tx.delete('timeBlocks',block.id);for(const item of plan.planned){const block={...item.block,generationOperationId:journal.operationId};await tx.put('timeBlocks',block);const task=await tx.get('tasks',item.task.id);if(task)await tx.put('tasks',{...task,status:'Scheduled',plannedMinutes:CoreUtil.num(task.plannedMinutes)+item.duration,updatedAt:CoreUtil.nowISO(),revision:CoreUtil.num(task.revision)+1})}await tx.put('activityLog',{id:CoreUtil.uid(),type:'schedule',text:`Applied ${plan.rescue?'Rescue Day':plan.minimum?'Minimum Day':'day plan'}`,meta:{...plan.summary,operationId:journal.operationId},at:CoreUtil.nowISO(),createdAt:CoreUtil.nowISO(),updatedAt:CoreUtil.nowISO()})});await this.journal.finish(journal,'committed');return{...plan,operationId:journal.operationId}}catch(error){await this.journal.finish(journal,'failed',error);throw error}}";
