const applyPlan="    async applyPlan(plan,event,context,{mode='production',confirmed=false}={}){if(!plan.matched)return{status:'Skipped',plan};if(plan.hardBlockers.length){if(mode==='production')await this.audit(plan.rule,event,'Blocked',plan.proposedActions,plan.hardBlockers,plan);return{status:'Blocked',plan}}if(mode!=='production')return{status:'Dry run',plan};if(plan.executionPolicy==='suggestion'){await this.audit(plan.rule,event,'Suggested',plan.proposedActions,[],plan);return{status:'Suggested',plan}}if(plan.requiresConfirmation&&!confirmed){await this.storePending(plan,event);await this.audit(plan.rule,event,'Awaiting confirmation',plan.proposedActions,[],plan);return{status:'Awaiting confirmation',plan}}let operation=null,repairResult=null;const repairAction=plan.proposedActions.find(action=>action.type==='run-minimal-repair');if(repairAction){if(!this.service)throw CoreUtil.error('RULE-REPAIR-EXECUTOR-018','Schedule repair executor is unavailable.');const preview=await this.service.buildRepair(repairAction.params.resolvedDate,{maxRadius:Math.max(1,Math.min(4,CoreUtil.num(repairAction.params.repairRadius,4)))});if(preview.sourceFingerprint!==repairAction.params.sourceFingerprint)throw CoreUtil.error('REPAIR-STALE-001','Schedule changed after the rule preview. Recalculate before applying.');repairResult=await this.service.applyRepair(preview,repairAction.params.candidateId,{skipOperationLock:true,label:'Automation — '+plan.rule.name,ruleMeta:{executionId:plan.executionId,ruleId:plan.rule.id,ruleName:plan.rule.name,triggerEventId:event.eventId,triggerType:event.type,status:'Applied',actions:plan.proposedActions.map(action=>action.type),blockers:[],warnings:plan.warnings,occurredAt:CoreUtil.nowISO()}});this.deferDomainEvent('schedule-repaired',{eventId:'schedule-repaired:'+repairResult.operationId,entityId:repairResult.operationId,current:{date:repairResult.date,stability:repairResult.stability.score,moved:repairResult.stability.movedBlockCount},data:{date:repairResult.date,movedBlockCount:repairResult.stability.movedBlockCount,stabilityAfter:repairResult.stability.score,operationId:repairResult.operationId,repairReason:'automation-minimal-repair'},sourceOperationId:repairResult.operationId,sourceRuleExecutionId:plan.executionId,sourceRuleId:plan.rule.id,parentRuleExecutionId:event.sourceRuleExecutionId||'',chainDepth:Math.min(MAX_RULE_CHAIN_DEPTH,event.chainDepth+1),lineage:[...new Set([...CoreUtil.array(event.lineage),plan.rule.id])].slice(-MAX_RULE_CHAIN_DEPTH)})}else{const mutation=this.taskChanges(plan,event,context);if(mutation.changes.length)operation=await this.undo.execute('Automation — '+plan.rule.name,mutation.changes,{activityType:'rule-automation',meta:{ruleExecution:{executionId:plan.executionId,ruleId:plan.rule.id,ruleName:plan.rule.name,triggerEventId:event.eventId,triggerType:event.type,status:'Applied',actions:plan.proposedActions.map(action=>action.type),blockers:[],warnings:plan.warnings,occurredAt:CoreUtil.nowISO()}},expectedRevisions:mutation.expectedRevisions})}let appliedSideEffect=false,suggestionOnly=false;for(const action of plan.proposedActions)if(action.type==='create-notification'){await this.notifyOnce(plan,event,action);appliedSideEffect=true}else if(action.type==='suggest-repair'){await this.notifications?.notify('INFO','Schedule repair suggested',plan.rule.name+' matched. Review Repair My Day before changing the schedule.',{persist:true});suggestionOnly=true}if(suggestionOnly&&!operation&&!repairResult&&!appliedSideEffect){await this.audit(plan.rule,event,'Suggested',plan.proposedActions,[],plan);return{status:'Suggested',plan}}if(!operation&&!repairResult)await this.audit(plan.rule,event,'Applied',plan.proposedActions,[],plan);plan.rule.lastEvaluatedAt=CoreUtil.nowISO();plan.rule.lastTriggeredAt=plan.rule.lastEvaluatedAt;await this.repo.save('rules',plan.rule);await this.pruneHistory();return{status:'Applied',plan,operation,repairResult}}";
