const confirmPending="    async confirmPending(executionId){const execute=async()=>{const state=await this.runtime(),pending=CoreUtil.array(state.pendingApprovals).find(row=>row.executionId===executionId);if(!pending)return{status:'Missing'};const rule=await this.repo.get('rules',pending.ruleId);if(!rule){await this.removePending(executionId);await this.audit(null,pending.event,'Stale',[],['Rule no longer exists.'],{executionId,conditionResults:[],warnings:[]});return{status:'Stale'}}const data=await this.repo.dataset({fresh:true}),settings=await this.repo.settings(),event=CoreUtil.clone(pending.event);for(const affected of CoreUtil.array(pending.affectedEntities)){const store=affected.type==='task'?'tasks':affected.type==='timeBlock'?'timeBlocks':affected.type==='settings'?'settings':'';if(!store)continue;const current=await this.repo.get(store,affected.id);if(!current||CoreUtil.num(current.revision)!==CoreUtil.num(affected.revision)){await this.removePending(executionId);await this.audit(rule,event,'Stale',pending.proposedActions,['Affected data changed after the automation preview. Review the rule again.'],{executionId,conditionResults:[],warnings:[]});return{status:'Stale'}}if(affected.type==='task')event.current=current}const context=this.context(event,data,settings),plan=this.evaluate(DataValidator.rule(rule),event,context);plan.executionId=executionId;plan.planId=pending.planId;const currentProposal=plan.proposedActions.map(action=>({type:action.type,params:CoreUtil.clone(action.params)})),previewProposal=CoreUtil.array(pending.proposedActions).map(action=>({type:action.type,params:CoreUtil.clone(action.params)}));if(!plan.matched||CoreUtil.hash(currentProposal)!==CoreUtil.hash(previewProposal)){await this.removePending(executionId);await this.audit(rule,event,'Stale',pending.proposedActions,[plan.matched?'Proposed action changed after the preview. Review the automation again.':'Conditions no longer match.'],plan);return{status:'Stale',plan}}plan.requiresConfirmation=false;plan.executionPolicy='automatic';if(plan.hardBlockers.length){await this.removePending(executionId);await this.audit(rule,event,'Blocked',plan.proposedActions,plan.hardBlockers,plan);return{status:'Blocked',plan}}try{const result=await this.applyPlan(plan,event,context,{mode:'production',confirmed:true});await this.removePending(executionId);return result}catch(error){await this.removePending(executionId);if(['DATA-STALE-010','DATA-REVISION-CONFLICT','UNDO-REVISION-001','SCENARIO-STALE-001','RULE-STALE-SCHEDULE-014','REPAIR-STALE-001'].includes(error.code)){await this.audit(rule,event,'Stale',plan.proposedActions,[error.message],plan);return{status:'Stale',plan,errorCode:error.code}}throw error}};const queued=this.processing.then(()=>this.operationLocks.withExclusiveLock('Rule approval',execute));this.processing=queued.catch(error=>{throw error});const result=await queued;await this.processing;await this.flushDeferredEvents();return result}";
