      const context={task:{id:'r451-task',title:'R451',status:'Next',priority:'Medium',estimatedDuration:45,minimumSessionDuration:15,maximumSessionDuration:90,actualMinutes:0,plannedMinutes:0,blockedBy:[],revision:1},data:{tasks:[],events:[],projects:[],timeBlocks:[],dayProfiles:[],dailyCheckins:[],focusSessions:[],activityLog:[]},settings:{...defaultSettings,id:'settings',revision:1,recoveryAfterWorkMinutes:30,deepWorkBefore:'16:00',taskTypePreferredBefore:{}},capacity:{focusRemaining:240},profile:'Off',time:'10:00',flexibleFocus:0,recoveryState:'None',stability:92,date:CoreUtil.localDate()};
      const pref45={type:'planning-preference',params:{kind:'recovery-after-work',minutes:45},definition:RULE_ACTIONS['planning-preference']},pref30={type:'planning-preference',params:{kind:'recovery-after-work',minutes:30},definition:RULE_ACTIONS['planning-preference']},deep={type:'planning-preference',params:{kind:'deep-work-before',time:'14:00'},definition:RULE_ACTIONS['planning-preference']};engine.resolvePlanningPreference(pref45,context);engine.resolvePlanningPreference(pref30,context);engine.resolvePlanningPreference(deep,context);
      await this.test('Rule Conflict Identity','same preference conflicts independent of proposed value',()=>this.assert(engine.conflictKey(pref45,{})===engine.conflictKey(pref30,{})));
