      await this.test('Rule Planning Preference','recovery preference resolves current and proposed values',()=>this.assert(pref45.params.currentValue===30&&pref45.params.proposedValue===45));
      await this.test('Rule Planning Preference','Deep Work cutoff validates civil time',()=>this.assert(deep.params.proposedValue==='14:00'));
      await this.test('Rule Planning Preference','invalid Deep Work cutoff is blocked',()=>{const action={type:'planning-preference',params:{kind:'deep-work-before',time:'25:00'},definition:RULE_ACTIONS['planning-preference']};this.assert(Boolean(engine.resolvePlanningPreference(action,context).blocker))});
      const suggested={type:'create-suggested-task',params:{title:'<script>alert(1)</script>',priority:'High'},definition:RULE_ACTIONS['create-suggested-task']};await this.test('Rule Suggested Task','task preview validates malicious title as inert text',()=>{const resolution=engine.resolveSuggestedTask(suggested,context);this.assert(!resolution.blocker&&suggested.params.title==='<script>alert(1)</script>')});
      const plan={executionId:'r451-exec',rule:{id:'r451-rule',name:'R451'},proposedActions:[suggested],warnings:[]},event={eventId:'r451-event',sourceRuleExecutionId:'',sourceOperationId:'',chainDepth:0,lineage:[]},mutation=engine.taskChanges(plan,event,context);await this.test('Rule Suggested Task','task creation produces one valid task change',()=>this.assert(mutation.changes.length===1&&mutation.changes[0].store==='tasks'&&DataValidator.task(mutation.changes[0].after).title==='<script>alert(1)</script>'));
      const prefPlan={executionId:'r451-pref-exec',rule:{id:'r451-pref-rule',name:'Preference'},proposedActions:[pref45],warnings:[]},prefMutation=engine.taskChanges(prefPlan,event,context);await this.test('Rule Planning Preference','approved preference produces validated settings mutation',()=>{const change=prefMutation.changes.find(row=>row.store==='settings');this.assert(change&&change.after.recoveryAfterWorkMinutes===45&&DataValidator.settings(change.after).recoveryAfterWorkMinutes===45)});
      await this.test('Rule Trigger Wiring','CivilTimeEngine projects Berlin civil midnight deterministically',()=>{const before=CivilTimeEngine.parts(Date.parse('2026-03-28T22:59:00Z'),'Europe/Berlin'),after=CivilTimeEngine.parts(Date.parse('2026-03-28T23:00:00Z'),'Europe/Berlin');this.assert(before.date==='2026-03-28'&&after.date==='2026-03-29')});
